const i=JSON.parse('{"workId":"xijing-zaji","chapter":{"id":"xijing-zaji_ch-1","workId":"xijing-zaji","order":1,"title":"第一","difficulty":4,"estimatedMinutes":10,"passageIds":["xijing-zaji_ch-1_p-1","xijing-zaji_ch-1_p-2","xijing-zaji_ch-1_p-3","xijing-zaji_ch-1_p-4","xijing-zaji_ch-1_p-5","xijing-zaji_ch-1_p-6","xijing-zaji_ch-1_p-7","xijing-zaji_ch-1_p-8","xijing-zaji_ch-1_p-9","xijing-zaji_ch-1_p-10","xijing-zaji_ch-1_p-11","xijing-zaji_ch-1_p-12","xijing-zaji_ch-1_p-13","xijing-zaji_ch-1_p-14","xijing-zaji_ch-1_p-15","xijing-zaji_ch-1_p-16","xijing-zaji_ch-1_p-17","xijing-zaji_ch-1_p-18","xijing-zaji_ch-1_p-19","xijing-zaji_ch-1_p-20","xijing-zaji_ch-1_p-21","xijing-zaji_ch-1_p-22","xijing-zaji_ch-1_p-23","xijing-zaji_ch-1_p-24","xijing-zaji_ch-1_p-25","xijing-zaji_ch-1_p-26","xijing-zaji_ch-1_p-27","xijing-zaji_ch-1_p-28","xijing-zaji_ch-1_p-29","xijing-zaji_ch-1_p-30"],"tags":[]},"passages":[{"id":"xijing-zaji_ch-1_p-1","chapterId":"xijing-zaji_ch-1","order":1,"canonicalText":"漢高帝七年，蕭相國營未央宮。因龍首山製前殿，建北闕。未央宮周迴二十二里九十五步五尺，街道周迴七十里，臺閣殿觀三十有二。西入武庫，東入太倉。前殿東西五十丈，深十五丈，高三十五丈。","sentenceIds":["xijing-zaji_ch-1_p-1_s-1","xijing-zaji_ch-1_p-1_s-2","xijing-zaji_ch-1_p-1_s-3","xijing-zaji_ch-1_p-1_s-4","xijing-zaji_ch-1_p-1_s-5"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢高祖七年，相國蕭何主持營建未央宮。依託龍首山的山勢修築前殿，修建巍峨的北闕門。未央宮外城周長二十二里九十五步五尺，宮內街道總周長達七十里，共有臺、閣、殿、觀等各類宏偉建築三十二座。宮西側通往國家武庫，東側通往皇家太倉。前殿東西寬達五十丈，南北進深十五丈，基座至屋頂高達三十五丈！","analysis":"【題解與蕭何營建未央宮之建築規制】本段為《西京雜記》開篇，詳載漢代長安未央宮之周長、臺閣、武庫太倉與前殿尺寸，是漢代都城考古與宮廷建築史之權威文獻。\\\\n【詞義訓詁】「蕭相國」：蕭何，漢初三傑之一；「因龍首山」：利用天然地形高臺修築前殿；「未央宮周迴」：漢代未央宮平面佈局規模；「三十五丈」：含高臺夯土基座之總高。\\\\n【天子威儀與建築政治學】蕭何以「天子以四海為家，非壯麗無以重威」之理念營造未央宮，奠定了兩漢大一統帝國之宮殿建築典範。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-2","chapterId":"xijing-zaji_ch-1","order":2,"canonicalText":"武帝作昆明池，欲伐昆吾夷，教習水戰。因而於上游戲養魚，魚給諸陵廟祭祀，餘付長安巿賣之。池周迴四十里，中作石鯨，長三丈，每至雷雨，往往鳴吼，鬣尾皆動。","sentenceIds":["xijing-zaji_ch-1_p-2_s-1","xijing-zaji_ch-1_p-2_s-2","xijing-zaji_ch-1_p-2_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"《西京雜記·卷一》第二節敘述：軍事防衛是關係國家安危的重大事務，切不可不審慎考察。英明的君主既嚴明法度又體恤百姓，尊崇禮義並推重賢能。天下的興盛與衰亡，完全取決於政治措施與道德教化。","analysis":"【主題與背景】\\\\\\\\n本段出自《西京雜記》卷一，記錄西漢初期在經歷秦末戰亂與楚漢相爭後，朝廷在建設長安城郭、安頓國防武備的同時，注重文治法度與賢能之士的招攬。\\\\\\\\n【詞義與名物】\\\\\\\\n兵者國之大事：軍事防務乃國家生存根本。\\\\\\\\n隆禮尊賢：崇尚禮樂，重用賢能人才（如西漢初期廣招天下賢士）。\\\\\\\\n政教：政令規範與道德教化。\\\\\\\\n【篇章解析】\\\\\\\\n本節凸顯西漢初期文武兼備的治國考量。面對邊境匈奴威脅與內部諸侯王割據，朝廷既重武備防衛（「兵者國之大事」），又重內部文治法度（「政教」），為漢朝長治久安奠定基石。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-3","chapterId":"xijing-zaji_ch-1","order":3,"canonicalText":"漢制：宗廟八月飲酎，用九醞太牢，皇帝侍祠。以正月旦作酒，八月成，名曰酎，一曰九醞，一名醇酎。諸侯各獻黃金以助祭，少者得罪，名曰酎金。","sentenceIds":["xijing-zaji_ch-1_p-3_s-1","xijing-zaji_ch-1_p-3_s-2","xijing-zaji_ch-1_p-3_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"《西京雜記·卷一》第三節指出：君子注重自身道德修養與反省，小人則是一味要求並責備他人。從個人的自我修養與家庭治理出發，進而實現治理國家與平定天下，這樣的功業典範將名垂青史，傳之久遠。","analysis":"【主題與背景】\\\\\\\\n本段出自《西京雜記》卷一結尾，總結西漢早期士大夫與宮廷知識份子以儒家內聖外王為理想追求的精神風貌。\\\\\\\\n【詞義與名物】\\\\\\\\n求諸己：反求諸己，自我嚴格要求。\\\\\\\\n修身齊家治國平天下：儒家經典《大學》的核心政治倫理與人生階梯。\\\\\\\\n憲章：永恆流傳的典章法則。\\\\\\\\n【篇章解析】\\\\\\\\n本節將長安宮廷人文與個人道德修養結合起來，強調漢代士人應以「修齊治平」自許，使個人功義與國家繁榮一同載於千秋史冊。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-4","chapterId":"xijing-zaji_ch-1","order":4,"canonicalText":"京師大水，祭山川以止雨。丞相御史二千石禱祠，如求雨法。設壇於城外，官吏素服，以祈天應。","sentenceIds":["xijing-zaji_ch-1_p-4_s-1","xijing-zaji_ch-1_p-4_s-2","xijing-zaji_ch-1_p-4_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"首都長安遭遇了嚴重的水災，朝廷於是祭祀名山大川來祈求停止降雨。丞相、御史大夫以及俸祿在二千石以上的高級官員們都親自參與祈禱和祭祀，儀式和規矩就如同求雨的方法一樣。他們在城外設立了祭壇，所有的官員都穿著白色的素服，以此來祈求上天的感應和憐憫。","analysis":"【訓詁與名物】「京師」指首都長安。「大水」指水災、洪澇。「丞相」百官之首。「御史」指御史大夫，與丞相、太尉合稱三公。「二千石」漢代高級官員的俸祿標準，代指郡守或九卿級別的高官。「禱祠」祈禱祭祀。「素服」白色的衣服，通常在凶事、災異或齋戒祈神時穿著，表示哀痛與誠敬。「天應」指上天的感應。\\\\n【章法與結構】本段以精煉的史家筆法紀錄了一場國家級的祈晴儀式。首句點明事件背景（京師大水）與核心行動（祭山川以止雨）；次句詳細列出參與祈禱的官員層級（丞相、御史、二千石），凸顯了朝廷對此次災變的重視程度；末句則描繪了具體的儀式場景（設壇城外，官吏素服），烘托出莊肅敬畏的氣氛。\\\\n【思想與義理】此段反映了漢代「天人感應」的政治神學觀。在古人看來，異常的自然災害（如大水）往往被視為上天對人類社會（特別是統治者）失德的警告。因此，面對水災，朝廷不僅需要實質的救災行動，更需要透過隆重的宗教儀式（祭山川、素服禱祠）來表達統治集團的恐懼與懺悔，期望透過這種「敬天」的姿態重新獲得上天的認可與庇佑，恢復自然界與社會的秩序。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-5","chapterId":"xijing-zaji_ch-1","order":5,"canonicalText":"天子筆管，以錯寶為跗，毛皆以秋兔之毫，官師路扈為之。以雜寶為匣，廁以玉璧翠羽，皆直百金。","sentenceIds":["xijing-zaji_ch-1_p-5_s-1","xijing-zaji_ch-1_p-5_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"皇帝所使用的毛筆，筆管的末端（跗）鑲嵌著各種錯落有致的寶石，筆毛全部採用秋天野兔的毫毛製成，這是由專門負責此事的工匠官員路扈所製作的。用各種珍寶做成裝筆的匣子，匣子上面還鑲嵌裝飾著玉璧和翠鳥的羽毛，這些東西每一件的價值都高達百兩黃金。","analysis":"【訓詁與名物】「天子」指皇帝。「錯寶」錯落鑲嵌的寶石。「跗」本指腳背，在此指筆管的末端或筆套。「秋兔之毫」秋天時兔子為了禦寒新長出的毛，最為堅挺銳利，是製筆的極品。「官師」古代掌管百工的官員。「路扈」人名，當時著名的製筆工匠。「匣」裝東西的盒子。「廁」通「側」或「雜」，在此指夾雜鑲嵌。「翠羽」翠鳥的羽毛。「直」通「值」，價值。\\\\n【章法與結構】本段詳細描繪了漢代宮廷御用文具的奢華。前半段聚焦於「筆」本身，從筆管的裝飾（錯寶為跗）到筆毛的選材（秋兔之毫），再點出製作者的身份（官師路扈），顯示其工藝之精湛；後半段則轉而描寫「筆匣」，羅列了「雜寶」、「玉璧」、「翠羽」等極其昂貴的裝飾材料，最後以「皆直百金」作結，將奢華程度推向頂點。\\\\n【思想與義理】《西京雜記》以記載西漢長安的宮廷祕史與奇珍異寶著稱。這段文字透過對一支小小毛筆及其包裝的工筆細描，生動折射出漢代皇室生活的極度奢靡。這種將日常實用工具（筆）徹底「藝術化」與「財富化」的現象，一方面展示了漢代工藝美術（如錯金銀、鑲嵌玉石羽毛）的卓越成就，另一方面也隱含了對統治階級窮奢極欲的某種客觀揭露。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-6","chapterId":"xijing-zaji_ch-1","order":6,"canonicalText":"漢制：天子玉幾，冬則加綈錦其上，謂之綈幾。以象牙為火籠，籠上皆散華文，後宮則五色綾文。以酒沃炭，則火光不耀而溫煖。","sentenceIds":["xijing-zaji_ch-1_p-6_s-1","xijing-zaji_ch-1_p-6_s-2","xijing-zaji_ch-1_p-6_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"大漢宮廷體制：天子的御案憑幾採用溫潤白玉雕琢，冬季寒冷時則在玉幾上覆蓋厚實溫暖的綈錦絲綢，稱為綈幾。宮中採用珍貴象牙雕刻成取暖的火籠，火籠外表面雕刻著精美的散花圖案，後宮嬪妃的火籠則裝飾著五彩斑斕的綾羅花紋。在炭火上澆灑美酒，炭火便不會發出刺眼耀眼的強光，卻能散發出持久醇厚的融融溫暖！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第一〉第 6 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「漢制天子玉幾冬則加綈錦其上謂之綈幾以象牙為火……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「漢」、「制」、「天」、「子」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-7","chapterId":"xijing-zaji_ch-1","order":7,"canonicalText":"武帝時，西域獻吉光裘，入水不濡。上時服此裘以聽朝。吉光神馬，出大月氏，其毛毛黃皮柔，百年不腐。","sentenceIds":["xijing-zaji_ch-1_p-7_s-1","xijing-zaji_ch-1_p-7_s-2","xijing-zaji_ch-1_p-7_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢武帝的時候，西域的國家進獻了一件吉光裘，這件皮草穿著入水也不會被沾濕。武帝經常穿著這件皮衣在朝廷上聽政。所謂的吉光，是一種傳說中的神馬，出產於大月氏國，牠的毛色發黃、皮質柔軟，即使過了一百年也不會腐壞。","analysis":"【訓詁與名物】「西域」漢代指玉門關、陽關以西的廣大地區。「吉光」古代神話傳說中的神獸，似馬。「裘」用毛皮做成的禦寒衣服。「濡」沾濕。「聽朝」皇帝上朝聽理政事。「大月氏」漢代西域的游牧民族國家。「百年不腐」形容其皮毛具有極強的防腐性與耐久性。\\\\n【章法與結構】本段記述了一件充滿奇幻色彩的西域貢品。文章首先點出事件的年代（武帝時）與物品的奇異特性（入水不濡）；接著描述了皇帝對此物的喜愛（時服此裘以聽朝）；最後對「吉光」這種神獸進行了考證式的補充說明，交代了牠的產地（大月氏）與物理特徵（毛黃皮柔、百年不腐），滿足了讀者的獵奇心理。\\\\n【思想與義理】漢武帝時期，張騫鑿空西域，開啟了中原與中亞地區頻繁的文化與物資交流。這段記載雖然帶有濃厚的神話傳說色彩（如入水不濡、百年不腐的吉光神馬），但它真實反映了漢代社會對於西域異國風情的強烈好奇與嚮往。武帝穿著西域異獸皮草上朝聽政的畫面，不僅彰顯了漢朝國力的強盛與萬邦來朝的威儀，也成為古代中外交通史上一個極具象徵意義的文化符號。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-8","chapterId":"xijing-zaji_ch-1","order":8,"canonicalText":"高帝、戚夫人善鼓瑟擊築。帝常擁夫人倚瑟而絃歌，畢，每泣下流漣。夫人善為翹袖折腰之舞，歌《出塞》、《入塞》之曲。","sentenceIds":["xijing-zaji_ch-1_p-8_s-1","xijing-zaji_ch-1_p-8_s-2","xijing-zaji_ch-1_p-8_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢高祖劉邦與寵妃戚夫人皆極其精通彈奏古瑟與敲擊築樂。高祖常常親切擁抱著戚夫人，倚靠著古瑟隨琴聲絃歌高唱；每當歌曲唱罷，高祖往往動情至深、淚水潸然漣漣而下。戚夫人極其擅長表演優美的翹袖折腰舞，動情歌唱深沉豪邁的《出塞》、《入塞》古曲。","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第一〉第 8 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「高帝戚夫人善鼓瑟擊築帝常擁夫人倚瑟而絃歌畢每……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「高」、「帝」、「戚」、「夫」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-9","chapterId":"xijing-zaji_ch-1","order":9,"canonicalText":"戚姬以百鍊金為彄環，照見指骨。上惡之，以賜侍兒鳴玉、耀光等，各四枚。","sentenceIds":["xijing-zaji_ch-1_p-9_s-1","xijing-zaji_ch-1_p-9_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"戚夫人用經過百次錘鍊的精金製作了扳指（彄環），這金屬光潔明亮到甚至能照出手指的骨頭。漢高祖劉邦非常討厭這件東西，於是戚夫人就把這東西賞賜給了名叫鳴玉、耀光等貼身侍女，每人分給了四枚。","analysis":"【訓詁與名物】「戚姬」即戚夫人，漢高祖劉邦的寵妃。「百鍊金」指經過反覆鍛打、純度極高的黃金。「彄環」讀ㄎㄡ ㄏㄨㄢˊ，古代套在手指上用以拉弓或裝飾的指環、扳指。「惡之」討厭它、對它感到反感。「侍兒」貼身侍女。「鳴玉」、「耀光」皆為侍女的名字。\\\\n【章法與結構】本段以簡潔的文字記錄了一件宮廷軼事。前半段描寫了物品的極度精美與詭異（百鍊金為彄環，照見指骨）；中間以「上惡之」三個字，突然扭轉了這件稀世珍寶在宮中的命運；後半段則交代了這件物品的最終去向（賜侍兒...各四枚）。情節轉折突兀卻又符合宮廷生活的隨意性。\\\\n【思想與義理】這段記載充滿了志怪與宮廷祕史的色彩。「照見指骨」的細節，將一件奢華的珠寶賦予了一種近乎妖異的透視感，這種違背常理的奇幻現象，自然引起了統治者（劉邦）的心理不適與忌諱（上惡之）。而在高祖死後慘遭呂後做成「人彘」的戚夫人，生前卻能將這種連皇帝都討厭的奇珍異寶隨意賞賜給下人，這不僅展現了她當時的受寵與豪奢，也為她日後悲慘的結局埋下了一種驕奢得禍的隱喻。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-10","chapterId":"xijing-zaji_ch-1","order":10,"canonicalText":"趙王如意年幼，未能親外傅。戚姬使舊趙王內傅趙媼傅之，號其室曰養德宮，後改為魚藻宮。","sentenceIds":["xijing-zaji_ch-1_p-10_s-1","xijing-zaji_ch-1_p-10_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"趙王劉如意當時年紀還很小，還沒有辦法親自跟隨外廷的男性太傅學習。戚夫人便派以前服侍過舊趙王的女傅趙老太太來教導他，並將他們居住的宮室命名為養德宮，後來又改名為魚藻宮。","analysis":"【訓詁與名物】「趙王如意」漢高祖與戚夫人所生之子劉如意，封為趙王。「外傅」古代教導貴族子弟的外廷男性老師。「內傅」在內宮中負責教導、保育皇子或公主的年長女性。「趙媼」讀ㄠˇ，姓趙的老婦人。「養德」涵養道德。「魚藻」《詩經·小雅》的篇名，常被用來借指宮廷池苑或宴樂之所。\\\\n【章法與結構】本段詳細交代了趙王如意幼年時期的教育安排與宮室更名。先說明起因（如意年幼，未能親外傅）；接著敘述戚夫人的應對措施（使趙媼傅之）；最後記錄了相關宮室名稱的演變（養德宮改魚藻宮）。記事平實，具有強烈的史料補遺性質。\\\\n【思想與義理】《西京雜記》對於漢初宮廷的細節有許多正史未載的補充。劉如意作為劉邦最寵愛的兒子，曾幾度差點取代太子劉盈的地位。這段記載表面上只是談論一個年幼皇子的保育問題，但「未能親外傅」卻由「內傅趙媼」教導，反映了戚夫人對兒子極度的保護與溺愛。而宮室名稱由嚴肅的「養德」改為帶有遊樂色彩的「魚藻」，似乎也隱隱暗示了這對母子在殘酷的政治鬥爭中，缺乏足夠的政治警覺與嚴格的政治訓練，最終雙雙死於呂後之手。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-11","chapterId":"xijing-zaji_ch-1","order":11,"canonicalText":"惠帝嘗與趙王同寢處，呂後欲殺之而未得。後帝早獵，王不能夙興，呂後命力士於被中縊殺之。及死，呂後令斷戚夫人手足，號曰人彘。","sentenceIds":["xijing-zaji_ch-1_p-11_s-1","xijing-zaji_ch-1_p-11_s-2","xijing-zaji_ch-1_p-11_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢惠帝（劉盈）因為想保護弟弟，曾經與趙王劉如意同喫同睡，呂後想要殺掉如意卻一直找不到機會。後來有一次惠帝清晨早起去打獵，趙王年幼無法早起同行，呂後便趁機命令大力士在被子裡將趙王勒死。等到趙王死後，呂後接著下令砍斷戚夫人的手腳（並挖去雙眼、燻聾雙耳、灌藥使之變啞），將她稱為人彘（人豬）。","analysis":"【訓詁與名物】「惠帝」漢高祖與呂後之子劉盈。「趙王」即劉如意。「寢處」起居作息。「未得」沒有得手、找不到機會。「夙興」早起。「縊殺」用繩索勒死。「人彘」彘讀ㄓˋ，豬；這是中國歷史上最殘酷的刑罰之一，將人截去四肢，破壞五官，丟入廁所中任其痛苦哀嚎。\\\\n【章法與結構】本段以極其冷靜的筆調，記錄了西漢初年最駭人聽聞的宮廷慘案。文章分為三個層次：首先描寫惠帝的仁慈保護與呂後的殺機暗藏形成僵局（同寢處...未得）；接著描寫僵局的打破，呂後趁隙痛下殺手（早獵...縊殺之）；最後寫呂後對情敵戚夫人展開了慘絕人寰的報復（斷手足...號曰人彘）。節奏緊湊，令人不寒而慄。\\\\n【思想與義理】這段記載展現了古代宮廷政治鬥爭的極度殘酷與人性底線的喪失。呂後為了鞏固兒子的皇位並發洩私憤，其手段之陰狠毒辣，達到了令人髮指的地步。而惠帝雖然本性仁厚（試圖以同寢處來保護弟弟），但在強勢且殘忍的母親面前，他的仁慈顯得軟弱無力，最終不僅未能保住弟弟，還因為看到了「人彘」的慘狀而受到巨大驚嚇，從此抑鬱成疾，不理朝政。這是一齣充滿了權力、嫉妒與人倫悲劇的歷史大戲。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-12","chapterId":"xijing-zaji_ch-1","order":12,"canonicalText":"樂遊苑自生玫瑰樹，樹下多苜蓿。苜蓿一名懷風，時人或謂之光風，風在其間，常蕭蕭然，日照其花，有光彩，故名光風。茂陵人謂之連枝草。","sentenceIds":["xijing-zaji_ch-1_p-12_s-1","xijing-zaji_ch-1_p-12_s-2","xijing-zaji_ch-1_p-12_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"樂遊苑裡自然生長著玫瑰樹，樹下長著許多苜蓿草。苜蓿草還有一個名字叫懷風，當時的人也有稱它為光風的，因為當風吹過草叢時，常會發出蕭蕭的風聲，而陽光照在它的花朵上，會閃爍出美麗的光彩，所以得名光風。茂陵一帶的人則稱它為連枝草。","analysis":"【訓詁與名物】「樂遊苑」漢代著名的皇家園林。「玫瑰」古代指一種開紅花的植物，或指一種紅色的美玉，此指植物。「苜蓿」一種豆科牧草，張騫出使西域時引入中國。「懷風」、「光風」、「連枝草」皆為苜蓿在漢代的各種別名。「蕭蕭然」形容風吹草動的聲音。\\\\n【章法與結構】本段是一則典型的植物名物考證。首句先點出植物生長的地點與環境（樂遊苑玫瑰樹下）；接著圍繞著「苜蓿」這個外來物種，詳細羅列並解釋了它在長安地區的各種別名（懷風、光風），並用優美的筆觸描述了「光風」得名的由來（風常蕭蕭然，日照有光彩）；最後補充了地方俗名（茂陵人謂之連枝草）。\\\\n【思想與義理】《西京雜記》不僅記錄政治軼事，也保存了大量漢代都城的風物名勝與自然生態紀錄。苜蓿作為漢武帝時期引進的重要戰馬飼料，在這段記載中卻褪去了其實用與軍事的色彩，轉而被賦予了極具詩意與審美情趣的名字（懷風、光風、連枝草）。這種對外來物種的本土化命名與審美觀照，生動地反映了漢代長安社會繁榮、浪漫且充滿生活情趣的都城文化氛圍。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-13","chapterId":"xijing-zaji_ch-1","order":13,"canonicalText":"終南山多離合草，葉似江蘺，而紅綠相雜，莖皆紫色，氣如蘿勒。有樹直上百丈，無枝，上結叢條如車蓋，名曰影樹。日中則影生，日落則影滅。","sentenceIds":["xijing-zaji_ch-1_p-13_s-1","xijing-zaji_ch-1_p-13_s-2","xijing-zaji_ch-1_p-13_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"終南山上生長著許多離合草，它的葉子長得像江蘺，紅色與綠色相間交雜，莖部都是紫色的，散發出的氣味就像蘿勒一樣。山上還有一種樹，樹幹筆直向上高達百丈，中間沒有分枝，到了頂端才結出像車蓋一樣的茂密枝條，名叫影樹。這種樹在正午陽光直射時會產生倒影，而太陽落下時倒影也就跟著消失了。","analysis":"【訓詁與名物】「終南山」位於長安城南，是秦嶺的主峯之一。「離合草」一種傳說中的奇草。「江蘺」一種香草。「蘿勒」即九層塔，一種帶有強烈香氣的植物。「百丈」形容極高。「車蓋」古代車輛上的傘狀遮蔽物。「影樹」傳說中的奇樹。\\\\n【章法與結構】本段連續記載了終南山上的兩種奇異植物。前半段寫「離合草」，主要從視覺的形態顏色（葉似江蘺、紅綠相雜、莖紫）與嗅覺的氣味（氣如蘿勒）進行細緻的白描；後半段寫「影樹」，則突出了其誇張的物理高度（直上百丈、無枝）與獨特的光影特性（日中影生，日落影滅），充滿了神祕的志怪色彩。\\\\n【思想與義理】這段文字展現了魏晉六朝筆記小說中常見的「博物志」風格。《西京雜記》作者對於終南山植物的描寫，混合了真實的植物特徵（如江蘺、蘿勒的氣味比喻）與誇張的文學想像（百丈無枝的影樹）。這種對名山大川中奇花異木的熱衷，不僅反映了古人對於未知自然界的好奇與探索欲，也為後世的古典文學與道家神仙志怪小說提供了豐富的想像素材與植物學原型。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-14","chapterId":"xijing-zaji_ch-1","order":14,"canonicalText":"漢帝相傳以秦王子嬰所奉白玉璽、高祖斬白蛇劍。劍上有七採珠、九華玉以為飾，雜廁五色琉璃為劍匣。匣上題曰：提三尺以取天下。","sentenceIds":["xijing-zaji_ch-1_p-14_s-1","xijing-zaji_ch-1_p-14_s-2","xijing-zaji_ch-1_p-14_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"大漢天子世世代代相傳的國家至寶，是當年秦王子嬰投降時向劉邦敬獻的白玉璽與漢高祖在芒碭山起義時的斬白蛇寶劍。寶劍之上鑲嵌著七彩寶珠與九華美玉作為尊貴裝飾，劍匣用五色斑斕的琉璃寶石交錯鑲嵌。劍匣之上鐫刻著雄壯銘文題辭道：提三尺寶劍以奪取天下！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第一〉第 14 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「漢帝相傳以秦王子嬰所奉白玉璽高祖斬白蛇劍劍上……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「漢」、「帝」、「相」、「傳」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-15","chapterId":"xijing-zaji_ch-1","order":15,"canonicalText":"漢綵女常以七月七日穿七孔鍼於開襟樓，俱以習之。相傳是夕織女渡河，宮人鹹乞巧焉。","sentenceIds":["xijing-zaji_ch-1_p-15_s-1","xijing-zaji_ch-1_p-15_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"大漢宮廷的宮女綵女們，每逢每年農曆七月初七七夕之夜，必定登上開襟樓舉行穿七孔針的乞巧競賽，宮女們皆爭相習練這項精巧技藝。民間相傳在這一天夜晚天上的織女跨越銀河與牛郎相會，宮廷宮女們無不在星空下虔誠向織女乞求賜予心靈手巧！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第一〉第 15 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「漢綵女常以七月七日穿七孔鍼於開襟樓俱以習之相……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「漢」、「綵」、「女」、「常」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-16","chapterId":"xijing-zaji_ch-1","order":16,"canonicalText":"宣帝被收擊郡邸獄，臂上猶帶史良娣合採婉轉絲繩，擊身毒國寶鏡一枚，大如八銖錢。舊傳此鏡見妖魅，持之可以照見五臟。","sentenceIds":["xijing-zaji_ch-1_p-16_s-1","xijing-zaji_ch-1_p-16_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢宣帝劉詢襁褓幼年遭受巫蠱之禍牽連被逮捕關押在郡邸獄中之際，幼小的手臂上依然繫著生母史良娣親手編織的五彩婉轉絲繩，絲繩上繫著一枚產自天竺身毒國的古老寶鏡，鏡子大小如同八銖錢幣一般。古老相傳這面寶鏡能夠照破妖魔鬼魅（見妖魅），隨身佩戴持握甚至能夠神奇地透視照見人體的五臟六腑！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第一〉第 16 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「宣帝被收擊郡邸獄臂上猶帶史良娣合採婉轉絲繩擊……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「宣」、「帝」、「被」、「收」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-17","chapterId":"xijing-zaji_ch-1","order":17,"canonicalText":"霍光妻遺淳于衍蒲桃錦二十四匹、散花綾二十五匹。綾出鉅鹿陳寶光家，寶光妻傳其法。霍顯召入其第，使作之。機用百二十躡，六十日成一匹，匹值萬錢。","sentenceIds":["xijing-zaji_ch-1_p-17_s-1","xijing-zaji_ch-1_p-17_s-2","xijing-zaji_ch-1_p-17_s-3","xijing-zaji_ch-1_p-17_s-4"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"大將軍霍光的妻子霍顯為了賄賂女醫淳于衍毒死許平君皇后，私下贈送給淳于衍二十四匹極其珍貴的葡萄紋錦緞（蒲桃錦）與二十五匹散花綾。這種名貴的散花綾出自鉅鹿郡紡織大師陳寶光家，由陳寶光的妻子世代傳承其獨門提花織造祕法。霍顯特意將陳寶光妻子召入霍府大宅，讓她專門織造。這套提花織機結構極其複雜，需要一百二十個踏板腳踏（百二十躡），耗時整整六十天才能織成一匹，每一匹散花綾價值高達一萬錢！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第一〉第 17 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「霍光妻遺淳于衍蒲桃錦二十四匹散花綾二十五匹綾……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「霍」、「光」、「妻」、「遺」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-18","chapterId":"xijing-zaji_ch-1","order":18,"canonicalText":"濟陰王興居反，始舉兵，大風從東來，直吹其旌旗，飛上天入雲，而墮城西井中。馬皆悲鳴不進。左右皆懼，後果兵敗自殺。","sentenceIds":["xijing-zaji_ch-1_p-18_s-1","xijing-zaji_ch-1_p-18_s-2","xijing-zaji_ch-1_p-18_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"濟陰王劉興居發動叛亂，剛開始起兵的時候，一陣大風從東邊刮來，直接吹向他的軍隊旌旗，把旌旗吹得飛上天空、沒入雲層，最後掉落在城西的一口水井裡。軍隊的戰馬全都發出悲涼的嘶鳴，不肯向前邁進。他身邊的部下都感到非常恐懼，後來他果然兵敗，自殺身亡。","analysis":"【訓詁與名物】「濟陰王興居」即劉興居，漢初齊悼惠王劉肥之子，在漢文帝時發動叛亂。「反」反叛。「舉兵」起兵。「旌旗」軍隊的旗幟，是全軍的指揮中心與精神象徵。「左右」身邊的親信部屬。\\\\n【章法與結構】本段是一則典型的「災異示警」故事。文章按照時間順序發展：起因是「興居反」；接著重點描繪起兵時發生的兩大異常現象：一是視覺上的異象（大風吹旗入井），二是聽覺與動物行為的異象（馬皆悲鳴不進）；這導致了軍心的動搖（左右皆懼）；最後以「後果兵敗自殺」作結，印證了先前的災異預兆。\\\\n【思想與義理】此段深刻反映了古代中國的「天人感應」與「災異占卜」觀念。在古人的戰爭心理學中，自然界的異常現象（如大風折旗）與動物的異常行為（如戰馬悲鳴），往往被解讀為上天對某項行動（特別是不義的叛亂）的否定與警告。這種災異現象會對軍隊的士氣造成毀滅性的打擊（左右皆懼）。作者透過記述這段史事，意在說明「逆天者亡」的傳統道德與政治規律。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-19","chapterId":"xijing-zaji_ch-1","order":19,"canonicalText":"五鹿充宗受學於弘成子。成子少時，嘗有人過己，授以文石，大如鷰卵。成子吞之，遂大明悟，為天下大儒。充宗得其傳，為梁丘《易》。","sentenceIds":["xijing-zaji_ch-1_p-19_s-1","xijing-zaji_ch-1_p-19_s-2","xijing-zaji_ch-1_p-19_s-3","xijing-zaji_ch-1_p-19_s-4"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢代學者五鹿充宗曾跟隨弘成子學習。弘成子年輕的時候，曾經有一個人經過他身邊，給了他一塊有花紋的石頭，大小就像燕子的蛋一樣。弘成子把這塊石頭吞了下去，從此便豁然開朗、智慧大增，成為了天下聞名的大儒。五鹿充宗得到了他的真傳，成為了精通《梁丘易》（《易經》流派之一）的一代經學大師。","analysis":"【訓詁與名物】「五鹿充宗」複姓五鹿，名充宗，漢元帝時期的經學名家。「弘成子」即弘恭，或傳說中的異人。「過己」經過自己身邊。「文石」帶有花紋的石頭。「鷰卵」燕子的蛋，形容石頭的大小。「明悟」頭腦聰明、領悟力大增。「大儒」學識淵博的儒家大師。「梁丘易」漢代《易經》的學派之一，由梁丘賀創立。\\\\n【章法與結構】本段記載了一段帶有神異色彩的學術傳承史。開頭先點明師承關係（五鹿充宗受學於弘成子）；接著以倒敘手法，插入了一段弘成子年輕時的奇遇（吞文石而大明悟），將儒學大師的智慧來源賦予了神仙道教般的傳奇色彩；最後再回到五鹿充宗身上，點出他繼承了這份傳奇學問，成為《梁丘易》的名家。\\\\n【思想與義理】漢代是經學昌盛的時代，同時也是讖緯神學與方士思想流行的時代。這段記載奇妙地將代表理性與經典考據的「大儒」身份，與代表神祕主義的「吞石得智」傳說結合在一起。這反映了漢代民間與文人對於知識權威的一種神化心理：他們認為那些能夠精通深奧經典（如《易經》）的宗師，其智慧往往並非純粹來自後天的苦讀，而是具有某種「天授」的神異機緣。這種筆記小說式的傳說，為嚴肅的學術史增添了濃厚的傳奇趣味。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-20","chapterId":"xijing-zaji_ch-1","order":20,"canonicalText":"始元元年，黃鵠下太液池。上為歌曰：「黃鵠飛兮下建章，羽肅肅兮行蹌蹌，金為衣兮菊為裳。唼喋荷浪，息宴蘭房。」","sentenceIds":["xijing-zaji_ch-1_p-20_s-1","xijing-zaji_ch-1_p-20_s-2","xijing-zaji_ch-1_p-20_s-3","xijing-zaji_ch-1_p-20_s-4"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢昭帝始元元年，有黃天鵝飛降在太液池中。皇帝為此作了一首歌，唱道：黃天鵝飛翔啊，降落在建章宮旁，羽毛發出肅肅的聲響啊，步伐從容優雅。彷彿穿著金黃色的上衣啊，又像是把菊花當作了下裳。牠們在荷葉翻滾的水波中啄食，在長滿蘭花的芳香居所中休息宴樂。","analysis":"【訓詁與名物】「始元元年」漢昭帝的年號，西元前86年。「黃鵠」黃色的天鵝，古人視為祥瑞之鳥。「太液池」漢代長安城建章宮北面的皇家池苑。「建章」即建章宮，漢武帝所建的宏大宮殿。「肅肅」形容鳥類拍打翅膀的聲音。「蹌蹌」形容步伐從容、儀態優雅。「唼喋」讀ㄕㄚˋ ㄓㄚˊ，水鳥在水中啄食水草與魚蝦的聲音。「蘭房」長滿蘭花的芳室，指美好的棲息地。\\\\n【章法與結構】本段以「史實記載」加「詩歌引述」的形式構成。首句簡明扼要地交代了時間、地點與祥瑞事件（始元元年黃鵠下太液池）；接著完整引錄了皇帝為此所作的楚辭體詩歌。詩歌本身對仗工整，從動態（飛、下）、聽覺（肅肅）、視覺顏色（金衣、菊裳），一路寫到水鳥的生活細節（唼喋、息宴），極具畫面感與節奏感。\\\\n【思想與義理】在漢代的天人感應學說中，「黃鵠」的降臨被視為國家祥瑞的重大標誌。漢昭帝繼位之初，急需確立自己統治的正當性與天命所歸的形象，因此太液池降下黃鵠，自然成為朝廷大書特書的政治事件。而這首帝王所作的《黃鵠歌》，辭藻華麗，意境優美，不僅展現了漢代楚辭文學的流風餘韻，也生動描繪了皇家園林（太液池、建章宮）中那種閒適、富麗且充滿神仙色彩的宮廷審美生活。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-21","chapterId":"xijing-zaji_ch-1","order":21,"canonicalText":"漢帝送死皆珠襦玉匣。匣形如鎧甲，連以金縷。武帝匣上皆鏤為蛟龍鸞鳳龜麟之象，世謂為蛟龍玉匣。梓宮以文梓為棺，題湊其上。","sentenceIds":["xijing-zaji_ch-1_p-21_s-1","xijing-zaji_ch-1_p-21_s-2","xijing-zaji_ch-1_p-21_s-3","xijing-zaji_ch-1_p-21_s-4"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"大漢天子崩逝下葬時皆穿戴奢華的珠襦玉匣（金縷玉衣）。玉匣的形狀如同古代戰士的鎧甲，用純金金絲（金縷）將數千片溫潤玉片精巧穿綴連綴在一起。漢武帝的金縷玉匣玉片上，每一片皆精心雕刻著蛟龍、鸞鳳、神龜、麒麟等神獸圖案，世人稱之為蛟龍玉匣！皇帝梓宮棺槨採用珍貴的文梓木製成內棺，外層用堅實黃腸木枋層層堆疊成黃腸題湊！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第一〉第 21 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「漢帝送死皆珠襦玉匣匣形如鎧甲連以金縷武帝匣上……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「漢」、「帝」、「送」、「死」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-22","chapterId":"xijing-zaji_ch-1","order":22,"canonicalText":"成帝設雲帳、雲幄、雲幕於甘泉紫殿，世謂三雲殿。皆以輕綃為之，風至則飄揚如雲氣。","sentenceIds":["xijing-zaji_ch-1_p-22_s-1","xijing-zaji_ch-1_p-22_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢成帝在甘泉宮的紫殿裡，設置了名為雲帳、雲幄、雲幕的華麗帳幔，當時的人將這裡稱為三雲殿。這些帳幔都是用極其輕薄的絲織品（輕綃）製作而成的，每當風吹過來的時候，帳幔就會隨風飄揚，看起來就像天空中的雲氣一樣。","analysis":"【訓詁與名物】「成帝」漢成帝劉驁，以奢靡荒淫著稱。「雲帳、雲幄、雲幕」三種不同規格與用途的帳幔，因其輕盈如雲而得名。「甘泉紫殿」甘泉宮是漢代的避暑行宮，紫殿為其中的宮殿。「輕綃」極其輕薄、透明的絲織品。「雲氣」天空中的雲霧。\\\\n【章法與結構】本段文字精練地記錄了漢代宮廷的奢華佈置。前一句客觀記錄了事件與名稱的由來（設三種帳幔於紫殿，故稱三雲殿）；後一句則揭示了這些帳幔的特殊材質（輕綃）以及它所營造出的夢幻視覺效果（風至則飄揚如雲氣）。兩句之間形成了「名」與「實」、「靜」與「動」的呼應。\\\\n【思想與義理】這段記載生動展現了漢成帝時期宮廷生活的極度奢靡與浪漫審美。成帝不惜耗費巨大的人力物力，用極其昂貴的「輕綃」來製作巨大的宮殿帳幔，其目的僅僅是為了追求一種「飄揚如雲氣」的視覺享受與神仙般的居住體驗。這種將生活起居極度藝術化、奇觀化的做法，雖然在工藝與美學上達到了極高的成就，但同時也折射出西漢中後期統治階層沉溺享樂、不問蒼生的政治腐敗，為西漢的衰亡埋下了伏筆。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-23","chapterId":"xijing-zaji_ch-1","order":23,"canonicalText":"漢掖庭有月影臺、雲光殿、九華殿、鳴鸞殿、開襟閣、臨池觀，不在簿籍，皆繁華窈窕之所棲宿焉。宮女數千，各極妖妍。","sentenceIds":["xijing-zaji_ch-1_p-23_s-1","xijing-zaji_ch-1_p-23_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢代的後宮（掖庭）中，有月影臺、雲光殿、九華殿、鳴鸞殿、開襟閣、臨池觀等許多宮苑建築，這些甚至都沒有記錄在朝廷正式的名冊籍貫上。這些地方都是那些姿態美好、容貌出眾的妃嬪與宮女居住的場所。裡面居住著數千名宮女，每一個人都極盡妖嬈美麗之能事。","analysis":"【訓詁與名物】「掖庭」漢代後宮的名稱，主管妃嬪與宮女。「臺、殿、閣、觀」皆為古代宮廷建築的不同形制。「簿籍」朝廷的官方檔案與名冊。「繁華窈窕」在此借代指容貌美麗、姿態優雅的年輕女子。「棲宿」居住。「妖妍」妖嬈美麗、豔麗動人。\\\\n【章法與結構】本段以鋪陳的手法描繪漢代後宮的龐大與奢華。首先一口氣羅列了六座名字極具詩意的宮苑建築（月影、雲光等），隨後補上一句驚人的論斷：「不在簿籍」，極言後宮建築之多，連官方檔案都無法完全記載。接著點出這些建築的用途（棲宿繁華窈窕），最後以「宮女數千，各極妖妍」八個字，將後宮佳麗三千的香艷與奢靡推向極致。\\\\n【思想與義理】《西京雜記》透過這種點名式的鋪排，生動再現了西漢盛世後宮的龐大規模與窮奢極欲。那些充滿浪漫文學色彩的宮殿名稱，與數千名「極極妖妍」的宮女交相輝映，勾勒出一幅紙醉金迷的宮廷畫卷。然而，「不在簿籍」四個字，除了誇飾其數量之多外，也隱含了一種對皇權無限擴張、後宮開支無度且不受官方體制監管的歷史批判意味。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-24","chapterId":"xijing-zaji_ch-1","order":24,"canonicalText":"趙飛鷰女弟居昭陽殿，中庭彤朱，而殿上丹漆，砌皆銅沓，黃金塗，白玉階，璧帶往往為黃金釭，含藍田璧，明珠翠羽飾之。","sentenceIds":["xijing-zaji_ch-1_p-24_s-1"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"趙飛燕的妹妹趙昭儀（趙合德）獨自居住在最奢華的昭陽殿之中：中庭庭院塗抹著鮮艷的硃砂紅土，宮殿柱樑刷著光亮的名貴丹漆，階梯包角全部鑲嵌著鍍金的青銅飾件（銅沓黃金塗），臺階由純淨白玉鋪就！牆壁的玉璧飾帶上到處鑲嵌著純金壁燈（黃金釭），燈中含著晶瑩剔透的藍田美玉，周圍點綴裝飾著碩大夜明珠與翠鳥羽毛！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第一〉第 24 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「趙飛鷰女弟居昭陽殿中庭彤朱而殿上丹漆砌皆銅沓……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「趙」、「飛」、「鷰」、「女」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-25","chapterId":"xijing-zaji_ch-1","order":25,"canonicalText":"積草池中有珊瑚樹，高一丈二尺，一本三柯，上有四百六十二條。是南越王趙他所獻，號為烽火樹。至夜光景常明，如火之照。","sentenceIds":["xijing-zaji_ch-1_p-25_s-1","xijing-zaji_ch-1_p-25_s-2","xijing-zaji_ch-1_p-25_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"積草池中生長著一株珊瑚樹，高度達到一丈二尺，一個主幹上分出三個大枝椏，上面總共有四百六十二根細枝條。這是當年南越王趙佗進獻給朝廷的貢品，被稱為烽火樹。到了夜晚，這棵樹依然會散發出明亮的光彩，就像燃燒的火光在照耀一樣。","analysis":"【訓詁與名物】「積草池」漢代長安皇家園林中的水池名。「一丈二尺」漢代一丈約合現在2.3米，此樹高近3米，極為罕見。「一本三柯」一個主幹，三個大枝。「條」細枝。「南越王趙他」即趙佗，秦末漢初割據嶺南的南越國建立者。「烽火樹」因其夜間發光如火而得名。「光景」光彩。\\\\n【章法與結構】本段以極其精確的數字與生動的視覺描寫，記錄了一件稀世珍寶。前半段如同一份科學考察報告，精確列出了珊瑚樹的高度（一丈二尺）、結構（一本三柯）與枝條數量（四百六十二條）；後半段則交代了它的來源（南越王趙佗獻），並解釋了它被稱為「烽火樹」的奇異原因（夜光常明，如火之照），令人稱奇。\\\\n【思想與義理】這段記載反映了漢代大一統帝國的廣闊疆域與豐富的朝貢文化。高達一丈二尺的紅珊瑚，在古代是極其罕見的海洋珍寶。南越王趙佗將此奇珍異寶進獻給漢朝皇帝，既是臣服的表示，也展示了嶺南與海洋地區獨特的物產。而這株會發光的「烽火樹」，不僅裝飾了漢代的皇家園林，也成為古人對於海洋世界充滿浪漫與神祕想像的具體載體，增添了長安城的帝國氣象。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-26","chapterId":"xijing-zaji_ch-1","order":26,"canonicalText":"昆明池刻玉石為魚，每至雷雨，魚常鳴吼，鬐尾皆動。漢世祭之以祈雨，往往有驗。","sentenceIds":["xijing-zaji_ch-1_p-26_s-1","xijing-zaji_ch-1_p-26_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"昆明池中不僅有石鯨，還雕刻有羊脂白玉石魚；每當天空中雷雨交加之際，玉石魚常常在波濤中發出奇妙的長鳴鳴吼，魚鰭與魚尾皆隨水流靈動擺動！漢代朝廷每逢大旱便前往祭祀白玉石魚以祈求甘霖降雨，往往每次祈雨皆有神奇的靈驗感應！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第一〉第 26 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「昆明池刻玉石為魚每至雷雨魚常鳴吼鬐尾皆動漢世……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「昆」、「明」、「池」、「刻」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-27","chapterId":"xijing-zaji_ch-1","order":27,"canonicalText":"初修上林苑，群臣遠方，各獻名果異樹，亦有製為美名，以摽奇麗。梨十：紫梨、青梨、芳梨、大谷梨、細葉梨、金村梨、夏梨、御兒梨、甘棠梨、香梨。棗七：滑棗、酸棗、細腰棗、羊角棗、大白棗、桂棗、牛頭棗。","sentenceIds":["xijing-zaji_ch-1_p-27_s-1","xijing-zaji_ch-1_p-27_s-2","xijing-zaji_ch-1_p-27_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"當初修建上林苑的時候，朝廷群臣以及遠方的各個國家，紛紛進獻名貴的水果與奇異的樹木，有些還特地為它們取了美麗的名字，用來標榜它們的奇特與華麗。其中單是梨子就有十種：包括紫梨、青梨、芳梨、大谷梨、細葉梨、金村梨、夏梨、御兒梨、甘棠梨、香梨。棗子也有七種：包括滑棗、酸棗、細腰棗、羊角棗、大白棗、桂棗、牛頭棗。","analysis":"【訓詁與名物】「上林苑」漢武帝擴建的宏大皇家園林，不僅是遊獵之所，也是收集天下奇花異草的植物園。「製」取名、制定。「摽」標榜、顯示。「奇麗」奇異美麗。「紫梨...香梨」皆為漢代引進或培育的梨樹品種。「滑棗...牛頭棗」皆為各種特徵各異的棗樹品種。\\\\n【章法與結構】本段是一則關於皇家園林植物多樣性的紀錄。開頭先總述上林苑修建時，各地進獻奇花異木的盛況，並點出古人喜愛為植物「製為美名，以摽奇麗」的文化心理；接著採用了目錄學式的列舉法，詳細條列了「梨十種」與「棗七種」的具體名稱。文字樸實無華，卻具有極高的史料價值。\\\\n【思想與義理】漢武帝修建上林苑，不僅僅是為了滿足個人的遊樂欲望，更是為了展現漢朝「包舉宇內、囊括四海」的帝國氣象。這段對於梨與棗各種奇特品種（如紫梨、羊角棗、牛頭棗）的詳細羅列，生動地證明瞭上林苑本質上是一個匯聚了天下奇珍的「國家植物園」。這種將天下萬物盡收於皇家園林之中的做法，象徵著大一統帝國對於自然資源的絕對壟斷與四海歸心的政治驕傲。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-28","chapterId":"xijing-zaji_ch-1","order":28,"canonicalText":"長安巧工丁緩者，為常滿燈，七龍五鳳，雜以芙蓉蓮藕之奇。又作臥褥香鑪，一名被中香鑪。本出房風，其法後絕，至緩始更為之。設機關，運轉四周，而鑪體常平，可置之被褥中，故以為名。","sentenceIds":["xijing-zaji_ch-1_p-28_s-1","xijing-zaji_ch-1_p-28_s-2","xijing-zaji_ch-1_p-28_s-3","xijing-zaji_ch-1_p-28_s-4"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"長安城有一位神乎其技的巧匠發明家名叫丁緩，他發明創製了自動調節油量的常滿燈，燈身雕刻有七條金龍與五隻彩鳳，交錯裝飾著出水芙蓉與蓮藕等精妙造型。丁緩又成功發明瞭臥褥香爐，又名被中香爐。這種香爐的製造原理本來源自上古房風氏，後來技術失傳絕跡，直到丁緩才重新研發復原出來！他在香爐內部設計了多層萬向同心圓環機械軸承裝置（設機關），無論香爐在被褥中如何翻滾旋轉四周，最中心的燃香爐體始終保持水平平衡、絕不會翻倒引發火災（鑪體常平），可以直接安放在被褥被窩之中取暖薰香，所以以此命名！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第一〉第 28 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「長安巧工丁緩者為常滿燈七龍五鳳雜以芙蓉蓮藕之……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「長」、「安」、「巧」、「工」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-29","chapterId":"xijing-zaji_ch-1","order":29,"canonicalText":"趙飛鷰為皇后，其女弟在昭陽殿，遺飛鷰書曰：「今日嘉辰，貴姊懋膺洪冊，謹上襚三十五條，以陳踴躍之懽。」有金錯連環、文犀簟、沉香水、九華扇、綠玉燈、百寶屏風。","sentenceIds":["xijing-zaji_ch-1_p-29_s-1","xijing-zaji_ch-1_p-29_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"趙飛燕被冊立為皇后的時候，她的妹妹趙合德當時居住在昭陽殿，寫了一封信給飛燕說：今天這個美好的日子，尊貴的姊姊您光榮地接受了皇后的冊封，我謹獻上三十五件珍貴的禮物，來表達我內心歡躍高興的心情。這些禮物中包含了金錯連環、帶有花紋的犀牛角竹蓆、沉香水、九華扇、綠玉做的燈臺，以及鑲嵌著百種珍寶的屏風等奇珍異寶。","analysis":"【訓詁與名物】「女弟」即妹妹，指趙合德。「懋膺」懋，勉力、光榮；膺，承受。指光榮地接受。「洪冊」指冊立皇后的重大詔書與典禮。「襚」讀ㄙㄨㄟˋ，本指贈送給死者的衣服，此處泛指贈送的衣物或珍貴禮物。「踴躍之懽」形容極度高興而歡躍。「文犀簟」用帶有美麗花紋的犀牛角裝飾或編織的涼蓆。「九華扇」一種極其精美華麗的扇子。\\\\n【章法與結構】本段記載了一件宮廷盛事及其奢侈的賀禮清單。前半段引用了趙合德寫給姊姊的賀信原文，文辭駢儷典雅（懋膺洪冊、踴躍之懽），展現了宮廷文書的華麗風格；後半段則轉入物品清單的羅列，一口氣報出了六種極其罕見、極具異國情調的珍寶名稱（金錯連環至百寶屏風），視覺衝擊力極強。\\\\n【思想與義理】這段文字生動地還原了西漢成帝時期「趙氏姐妹」專寵後宮的奢靡畫卷。趙飛燕與趙合德出身微賤，卻憑藉美貌與手段登上了權力的頂峯。妹妹送給姊姊的這份多達「三十五條」的賀禮清單，每一件都是價值連城的奇珍異寶。這種姐妹間近乎炫耀式的相互贈答，不僅展示了漢代工藝品極高的藝術水準（如文犀簟、綠玉燈），更折射出當時後宮權力的傲慢與物質享受的窮奢極欲。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-1_p-30","chapterId":"xijing-zaji_ch-1","order":30,"canonicalText":"趙後體輕腰弱，善行步進退，女弟昭儀不能及也。但昭儀弱骨豐肌，尤工笑語。二人並色如紅玉，為當時所絕。成帝專寵，六宮無色。","sentenceIds":["xijing-zaji_ch-1_p-30_s-1","xijing-zaji_ch-1_p-30_s-2","xijing-zaji_ch-1_p-30_s-3","xijing-zaji_ch-1_p-30_s-4"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"趙飛燕皇后身輕如燕、腰肢纖細柔弱，極其擅長優雅曼妙的漫步走姿與進退舞步（善行步進退），這一點是她的妹妹趙昭儀所趕不上的；然而趙昭儀骨骼柔弱而肌膚豐盈圓潤（弱骨豐肌），尤其極其擅長甜美溫柔的談笑耳語。姐妹二人皆肌膚晶瑩剔透、面色嬌艷紅潤如同天然紅玉，乃是當世絕無僅有的天下尤物！漢成帝對她們姐妹二人專寵至極，使得後宮六宮粉黛三千佳麗全部黯然失色！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第一〉第 30 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「趙後體輕腰弱善行步進退女弟昭儀不能及也但昭儀……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「趙」、「後」、「體」、「輕」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}}],"sentences":[{"id":"xijing-zaji_ch-1_p-1_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-1","order":1,"canonicalText":"漢高帝七年，蕭相國營未央宮。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-1_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-1","order":2,"canonicalText":"因龍首山製前殿，建北闕。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-1_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-1","order":3,"canonicalText":"未央宮周迴二十二里九十五步五尺，街道周迴七十里，臺閣殿觀三十有二。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-1_s-4","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-1","order":4,"canonicalText":"西入武庫，東入太倉。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-1_s-5","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-1","order":5,"canonicalText":"前殿東西五十丈，深十五丈，高三十五丈。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-2_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-2","order":1,"canonicalText":"武帝作昆明池，欲伐昆吾夷，教習水戰。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-2_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-2","order":2,"canonicalText":"因而於上游戲養魚，魚給諸陵廟祭祀，餘付長安巿賣之。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-2_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-2","order":3,"canonicalText":"池周迴四十里，中作石鯨，長三丈，每至雷雨，往往鳴吼，鬣尾皆動。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-3_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-3","order":1,"canonicalText":"漢制：宗廟八月飲酎，用九醞太牢，皇帝侍祠。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-3_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-3","order":2,"canonicalText":"以正月旦作酒，八月成，名曰酎，一曰九醞，一名醇酎。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-3_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-3","order":3,"canonicalText":"諸侯各獻黃金以助祭，少者得罪，名曰酎金。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-4_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-4","order":1,"canonicalText":"京師大水，祭山川以止雨。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-4_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-4","order":2,"canonicalText":"丞相御史二千石禱祠，如求雨法。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-4_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-4","order":3,"canonicalText":"設壇於城外，官吏素服，以祈天應。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-5_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-5","order":1,"canonicalText":"天子筆管，以錯寶為跗，毛皆以秋兔之毫，官師路扈為之。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-5_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-5","order":2,"canonicalText":"以雜寶為匣，廁以玉璧翠羽，皆直百金。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-6_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-6","order":1,"canonicalText":"漢制：天子玉幾，冬則加綈錦其上，謂之綈幾。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-6_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-6","order":2,"canonicalText":"以象牙為火籠，籠上皆散華文，後宮則五色綾文。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-6_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-6","order":3,"canonicalText":"以酒沃炭，則火光不耀而溫煖。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-7_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-7","order":1,"canonicalText":"武帝時，西域獻吉光裘，入水不濡。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-7_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-7","order":2,"canonicalText":"上時服此裘以聽朝。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-7_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-7","order":3,"canonicalText":"吉光神馬，出大月氏，其毛毛黃皮柔，百年不腐。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-8_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-8","order":1,"canonicalText":"高帝、戚夫人善鼓瑟擊築。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-8_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-8","order":2,"canonicalText":"帝常擁夫人倚瑟而絃歌，畢，每泣下流漣。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-8_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-8","order":3,"canonicalText":"夫人善為翹袖折腰之舞，歌《出塞》、《入塞》之曲。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-9_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-9","order":1,"canonicalText":"戚姬以百鍊金為彄環，照見指骨。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-9_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-9","order":2,"canonicalText":"上惡之，以賜侍兒鳴玉、耀光等，各四枚。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-10_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-10","order":1,"canonicalText":"趙王如意年幼，未能親外傅。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-10_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-10","order":2,"canonicalText":"戚姬使舊趙王內傅趙媼傅之，號其室曰養德宮，後改為魚藻宮。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-11_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-11","order":1,"canonicalText":"惠帝嘗與趙王同寢處，呂後欲殺之而未得。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-11_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-11","order":2,"canonicalText":"後帝早獵，王不能夙興，呂後命力士於被中縊殺之。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-11_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-11","order":3,"canonicalText":"及死，呂後令斷戚夫人手足，號曰人彘。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-12_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-12","order":1,"canonicalText":"樂遊苑自生玫瑰樹，樹下多苜蓿。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-12_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-12","order":2,"canonicalText":"苜蓿一名懷風，時人或謂之光風，風在其間，常蕭蕭然，日照其花，有光彩，故名光風。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-12_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-12","order":3,"canonicalText":"茂陵人謂之連枝草。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-13_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-13","order":1,"canonicalText":"終南山多離合草，葉似江蘺，而紅綠相雜，莖皆紫色，氣如蘿勒。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-13_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-13","order":2,"canonicalText":"有樹直上百丈，無枝，上結叢條如車蓋，名曰影樹。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-13_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-13","order":3,"canonicalText":"日中則影生，日落則影滅。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-14_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-14","order":1,"canonicalText":"漢帝相傳以秦王子嬰所奉白玉璽、高祖斬白蛇劍。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-14_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-14","order":2,"canonicalText":"劍上有七採珠、九華玉以為飾，雜廁五色琉璃為劍匣。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-14_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-14","order":3,"canonicalText":"匣上題曰：提三尺以取天下。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-15_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-15","order":1,"canonicalText":"漢綵女常以七月七日穿七孔鍼於開襟樓，俱以習之。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-15_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-15","order":2,"canonicalText":"相傳是夕織女渡河，宮人鹹乞巧焉。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-16_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-16","order":1,"canonicalText":"宣帝被收擊郡邸獄，臂上猶帶史良娣合採婉轉絲繩，擊身毒國寶鏡一枚，大如八銖錢。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-16_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-16","order":2,"canonicalText":"舊傳此鏡見妖魅，持之可以照見五臟。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-17_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-17","order":1,"canonicalText":"霍光妻遺淳于衍蒲桃錦二十四匹、散花綾二十五匹。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-17_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-17","order":2,"canonicalText":"綾出鉅鹿陳寶光家，寶光妻傳其法。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-17_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-17","order":3,"canonicalText":"霍顯召入其第，使作之。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-17_s-4","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-17","order":4,"canonicalText":"機用百二十躡，六十日成一匹，匹值萬錢。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-18_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-18","order":1,"canonicalText":"濟陰王興居反，始舉兵，大風從東來，直吹其旌旗，飛上天入雲，而墮城西井中。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-18_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-18","order":2,"canonicalText":"馬皆悲鳴不進。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-18_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-18","order":3,"canonicalText":"左右皆懼，後果兵敗自殺。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-19_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-19","order":1,"canonicalText":"五鹿充宗受學於弘成子。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-19_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-19","order":2,"canonicalText":"成子少時，嘗有人過己，授以文石，大如鷰卵。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-19_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-19","order":3,"canonicalText":"成子吞之，遂大明悟，為天下大儒。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-19_s-4","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-19","order":4,"canonicalText":"充宗得其傳，為梁丘《易》。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-20_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-20","order":1,"canonicalText":"始元元年，黃鵠下太液池。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-20_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-20","order":2,"canonicalText":"上為歌曰：「黃鵠飛兮下建章，羽肅肅兮行蹌蹌，金為衣兮菊為裳。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-20_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-20","order":3,"canonicalText":"唼喋荷浪，息宴蘭房。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-20_s-4","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-20","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-21_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-21","order":1,"canonicalText":"漢帝送死皆珠襦玉匣。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-21_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-21","order":2,"canonicalText":"匣形如鎧甲，連以金縷。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-21_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-21","order":3,"canonicalText":"武帝匣上皆鏤為蛟龍鸞鳳龜麟之象，世謂為蛟龍玉匣。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-21_s-4","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-21","order":4,"canonicalText":"梓宮以文梓為棺，題湊其上。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-22_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-22","order":1,"canonicalText":"成帝設雲帳、雲幄、雲幕於甘泉紫殿，世謂三雲殿。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-22_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-22","order":2,"canonicalText":"皆以輕綃為之，風至則飄揚如雲氣。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-23_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-23","order":1,"canonicalText":"漢掖庭有月影臺、雲光殿、九華殿、鳴鸞殿、開襟閣、臨池觀，不在簿籍，皆繁華窈窕之所棲宿焉。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-23_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-23","order":2,"canonicalText":"宮女數千，各極妖妍。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-24_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-24","order":1,"canonicalText":"趙飛鷰女弟居昭陽殿，中庭彤朱，而殿上丹漆，砌皆銅沓，黃金塗，白玉階，璧帶往往為黃金釭，含藍田璧，明珠翠羽飾之。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-25_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-25","order":1,"canonicalText":"積草池中有珊瑚樹，高一丈二尺，一本三柯，上有四百六十二條。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-25_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-25","order":2,"canonicalText":"是南越王趙他所獻，號為烽火樹。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-25_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-25","order":3,"canonicalText":"至夜光景常明，如火之照。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-26_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-26","order":1,"canonicalText":"昆明池刻玉石為魚，每至雷雨，魚常鳴吼，鬐尾皆動。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-26_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-26","order":2,"canonicalText":"漢世祭之以祈雨，往往有驗。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-27_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-27","order":1,"canonicalText":"初修上林苑，群臣遠方，各獻名果異樹，亦有製為美名，以摽奇麗。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-27_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-27","order":2,"canonicalText":"梨十：紫梨、青梨、芳梨、大谷梨、細葉梨、金村梨、夏梨、御兒梨、甘棠梨、香梨。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-27_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-27","order":3,"canonicalText":"棗七：滑棗、酸棗、細腰棗、羊角棗、大白棗、桂棗、牛頭棗。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-28_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-28","order":1,"canonicalText":"長安巧工丁緩者，為常滿燈，七龍五鳳，雜以芙蓉蓮藕之奇。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-28_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-28","order":2,"canonicalText":"又作臥褥香鑪，一名被中香鑪。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-28_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-28","order":3,"canonicalText":"本出房風，其法後絕，至緩始更為之。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-28_s-4","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-28","order":4,"canonicalText":"設機關，運轉四周，而鑪體常平，可置之被褥中，故以為名。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-29_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-29","order":1,"canonicalText":"趙飛鷰為皇后，其女弟在昭陽殿，遺飛鷰書曰：「今日嘉辰，貴姊懋膺洪冊，謹上襚三十五條，以陳踴躍之懽。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-29_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-29","order":2,"canonicalText":"」有金錯連環、文犀簟、沉香水、九華扇、綠玉燈、百寶屏風。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-30_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-30","order":1,"canonicalText":"趙後體輕腰弱，善行步進退，女弟昭儀不能及也。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-30_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-30","order":2,"canonicalText":"但昭儀弱骨豐肌，尤工笑語。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-30_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-30","order":3,"canonicalText":"二人並色如紅玉，為當時所絕。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-1_p-30_s-4","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-1","passageId":"xijing-zaji_ch-1_p-30","order":4,"canonicalText":"成帝專寵，六宮無色。","chunks":[],"tags":[]}]}');export{i as default};
